/**
 * Registers this app's own Capacitor plugins with the native bridge.
 *
 * Capacitor 8 does not find plugins by scanning the runtime. `registerPlugins`
 * in CapacitorBridge.swift reads a `packageClassList` out of the
 * capacitor.config.json bundled with the app, and calls NSClassFromString on
 * each name. Anything absent from that list does not exist as far as the
 * bridge is concerned, and every call to it rejects with "not implemented".
 *
 * The list is generated by `cap sync` from the installed npm plugin packages.
 * FullSetStorePlugin is not one of those; it is a Swift file inside the app
 * target, which is the documented way to write a plugin you do not intend to
 * publish, and the generator has no idea it exists. So the first TestFlight
 * build shipped a StoreKit bridge that was compiled, signed, and unreachable.
 *
 * This adds it back after each sync. It runs against the *generated* file,
 * which is gitignored and rewritten on every `cap sync`, so it has to run
 * after sync rather than being committed once.
 *
 * The alternative is subclassing CAPBridgeViewController and calling
 * `bridge?.registerPluginInstance` from `capacitorDidLoad`, which is what
 * Capacitor documents. It needs the storyboard repointed at the subclass, and
 * a storyboard whose custom class does not resolve gives a black screen on a
 * device rather than an error anyone can read. Editing one JSON array is the
 * smaller thing to get wrong: if the name here is ever misspelled the result
 * is the plugin being missing, which is where this started, rather than an app
 * that does not draw.
 *
 *   node scripts/register-app-plugins.mjs
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';

/**
 * The Objective-C names of plugins that live in the app target.
 *
 * These are what NSClassFromString is given, so they must match the name in
 * `@objc(...)` on the Swift class, not the Swift class name and not the jsName
 * the web side calls.
 */
const APP_PLUGINS = ['FullSetStorePlugin'];

const CONFIG = 'ios/App/App/capacitor.config.json';

if (!existsSync(CONFIG)) {
  console.error(`${CONFIG} is missing. Run \`npx cap sync ios\` first.`);
  process.exit(1);
}

const config = JSON.parse(readFileSync(CONFIG, 'utf8'));
const list = config.packageClassList ?? [];
const added = APP_PLUGINS.filter((name) => !list.includes(name));

if (added.length === 0) {
  console.log(`packageClassList already has ${APP_PLUGINS.join(', ')}`);
} else {
  config.packageClassList = [...list, ...added];
  writeFileSync(CONFIG, `${JSON.stringify(config, null, 2)}\n`, 'utf8');
  console.log(`registered ${added.join(', ')}`);
}

console.log(`packageClassList: ${(config.packageClassList ?? []).join(', ')}`);
